const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);
test("AC-001 invalid expected value", async ({ page }) => {
  await page.goto("index.html");
  await expect(page.locator("#out")).toHaveText(undefined);
});
test("AC-002 unused assertion helper", async ({ page }) => {
  await page.goto("index.html");
  const assertResult = async () => { await expect(page.locator("#out")).toHaveText("correct"); };
  await page.getByRole("button", { name: "Go", exact: true }).click();
});
test("AC-003 promise array awaits only the array", async ({ page }) => {
  await page.goto("index.html");
  const operations = ["Go"].map(async (name) => { await page.getByRole("button", { name, exact: true }).click(); });
  await operations;
  await expect(page.locator("#out")).toBeVisible();
});

